python3 -I -c "import pathlib,json,hashlib; paths=['docs/perpetua/operating-parameters.md','.session/exports/actions/43652564966.json','.session/exports/reports/643.json','.session/exports/records/0138.json'];
for n in paths:
 p=pathlib.Path(n); print(n, 'exists', p.exists());
 if p.exists():
  b=p.read_bytes(); print('bytes',len(b),'sha256',hashlib.sha256(b).hexdigest()); d=json.loads(b) if n.endswith('.json') else None; print('shape',[(k,type(v).__name__) for k,v in d.items()] if isinstance(d,dict) else b.decode() if d is None else type(d).__name__)"

python3 -I -c "import pathlib,json,hashlib; m=json.loads(pathlib.Path('.session/exports/manifest.json').read_text());
for x in m['results']:
 if x['source']!='actions': continue
 p=pathlib.Path('.session')/x['path']; b=p.read_bytes(); d=json.loads(b); print('SESSION',x['issue'],'PATH',str(p),'SHA256',hashlib.sha256(b).hexdigest()); print({k:d.get(k) for k in ['id','status','conclusion','created_at','run_started_at','updated_at','run_attempt']});
 for j in d['jobs']:
  print('JOB',{k:j.get(k) for k in ['id','name','status','conclusion','started_at','completed_at']});
  for s in j.get('steps',[]): print('STEP',{k:s.get(k) for k in ['number','name','status','conclusion','started_at','completed_at']})"

